from pwn import *
import time

binary = './pgtp'

env = {"LD_LIBRARY_PATH": "./libs"}

p = process(binary, cwd='.', env=env)

transcript = []
def recv_until_prompt():
    data = b''
    while True:
        chunk = p.recv(timeout=1)
        if not chunk:
            break
        data += chunk
        if b'> ' in data or b'Exit' in data or b'exit' in data or b'Enter' in data:
            break
    return data

# Grab banner and initial menu or prompt
try:
    transcript.append(recv_until_prompt())
    for choice in ['1', '2', '3', '4', '5', 'A', 'a', 'Q', 'q', 'test', '%p %p %p', '\n']:
        p.sendline(str(choice))
        time.sleep(0.2)
        transcript.append(recv_until_prompt())
    p.close()
except EOFError:
    pass
except Exception as e:
    transcript.append(str(e).encode())
    try:
        p.close()
    except Exception:
        pass

with open("pgtp_transcript.txt", "wb") as f:
    for entry in transcript:
        f.write(entry)
        f.write(b"\n===\n")

